// This file is automatically generated. Do not edit it directly.
//
// NOTE: the "automatically generated" header above refers to the Supabase CLI
// regenerating `./types.ts`. The client construction below is owned by us and
// is intentionally hardened against module-evaluation boot crashes — without
// this guard, calling `createClient(undefined, undefined)` throws synchronously
// at import time (supabase-js: "supabaseUrl is required."), which propagates
// through services/db -> AuthContext -> App and prevents `root.render()` from
// ever being reached. See plan: harden supabase/client.ts against module-eval
// boot failure.
import { createClient, type SupabaseClient } from '@supabase/supabase-js';
import type { Database } from './types';

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL as string | undefined;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as
  | string
  | undefined;

// ── Env validation ─────────────────────────────────────────────────────────
//
// Cover three failure classes explicitly (not just `undefined`):
//   1. missing             — var not defined at build time
//   2. empty / whitespace  — defined but blank
//   3. invalid shape       — placeholder text, unresolved `${VAR}` template,
//                            literal "undefined"/"null", non-URL value, or a
//                            key obviously too short to be a real anon key
//
// On any failure we do NOT call createClient (which would throw synchronously
// during module evaluation). Instead we export a Proxy with the same TS type
// as the real client; the first meaningful property access throws a
// descriptive, actionable error that surfaces through GlobalErrorBoundary.

type EnvStatus =
  | "ok"
  | "missing"
  | "empty"
  | "placeholder"
  | "invalid-url-shape"
  | "too-short";

function classifyCommon(v: string | undefined): EnvStatus | "ok-so-far" {
  if (typeof v !== "string") return "missing";
  const trimmed = v.trim();
  if (trimmed.length === 0) return "empty";
  if (
    trimmed === "undefined" ||
    trimmed === "null" ||
    trimmed.includes("${")
  ) {
    return "placeholder";
  }
  return "ok-so-far";
}

function classifyUrl(v: string | undefined): EnvStatus {
  const base = classifyCommon(v);
  if (base !== "ok-so-far") return base;
  // supabase-js builds `${url}/auth/v1`, `${url}/rest/v1`, etc. and also calls
  // `new URL(this.authUrl)`. Anything that isn't an http(s) URL would later
  // throw "Invalid URL" deep inside a sub-client; reject up front.
  return /^https?:\/\/[^\s]+$/i.test((v as string).trim())
    ? "ok"
    : "invalid-url-shape";
}

function classifyKey(v: string | undefined): EnvStatus {
  const base = classifyCommon(v);
  if (base !== "ok-so-far") return base;
  // Real anon / publishable keys (legacy JWT or new sb_publishable_*) are
  // always comfortably longer than 20 chars. This rejects obvious dev
  // placeholders like "TODO", "xxx", "changeme".
  return (v as string).trim().length >= 20 ? "ok" : "too-short";
}

const URL_STATUS = classifyUrl(SUPABASE_URL);
const KEY_STATUS = classifyKey(SUPABASE_PUBLISHABLE_KEY);

/**
 * `true` iff the Supabase env is missing, empty, or has an invalid shape and
 * the exported `supabase` is therefore a throw-on-use Proxy stub rather than a
 * real client. Opt-in pre-flight code (diagnostics page,
 * `validateIntegrationsBoot`) can read this without a try/catch.
 */
export const supabaseEnvMissing: boolean =
  URL_STATUS !== "ok" || KEY_STATUS !== "ok";

function buildDiagnosticMessage(attemptedAccess?: string): string {
  const lines = [
    "[supabase/client] Supabase client is not configured.",
    `  VITE_SUPABASE_URL: ${URL_STATUS}`,
    `  VITE_SUPABASE_PUBLISHABLE_KEY: ${KEY_STATUS}`,
    "Database, auth, and storage calls cannot succeed until both variables are set to valid values and the app is re-deployed.",
  ];
  if (attemptedAccess !== undefined) {
    lines.push(`(attempted access: .${attemptedAccess})`);
  }
  return lines.join("\n");
}

function createUnconfiguredClient(): SupabaseClient<Database> {
  // Property keys that must NOT throw — devtools, logging, React internals,
  // structured-clone probes, accidental `await` (`then`), and Symbol-based
  // protocol checks all touch these and would otherwise produce noisy
  // secondary errors that obscure the real diagnostic.
  const SAFE_STRING_KEYS = new Set<string>([
    "then", // critical: prevents `await supabase` from triggering the throw
    "toJSON",
    "toString",
    "valueOf",
    "constructor",
    "$$typeof",
    "nodeType",
  ]);

  const handler: ProxyHandler<object> = {
    get(_target, prop) {
      if (typeof prop === "symbol") {
        if (prop === Symbol.toPrimitive) {
          return () => "[supabase: env missing]";
        }
        if (prop === Symbol.toStringTag) {
          return "SupabaseClientStub";
        }
        // Symbol.iterator, Symbol.asyncIterator, and any other symbol
        // probe -> undefined (lets standard "not iterable" / protocol-miss
        // errors surface naturally instead of our throw).
        return undefined;
      }
      if (SAFE_STRING_KEYS.has(prop)) {
        return undefined;
      }
      throw new Error(buildDiagnosticMessage(prop));
    },
    apply() {
      throw new Error(buildDiagnosticMessage("()"));
    },
    construct() {
      throw new Error(buildDiagnosticMessage("new ()"));
    },
  };

  // Cast is honest: the Proxy stands in for SupabaseClient<Database> and
  // throws on every real method access. No call site needs a null-check; no
  // method is silently no-op'd. This is the agreed boundary: same TS type,
  // honest runtime failure.
  return new Proxy({}, handler) as unknown as SupabaseClient<Database>;
}

let exportedClient: SupabaseClient<Database>;

if (supabaseEnvMissing) {
  // Emit once at module-eval time so the diagnostic is visible in the console
  // even before the first call site trips the Proxy.
  console.error(buildDiagnosticMessage());
  exportedClient = createUnconfiguredClient();
} else {
  exportedClient = createClient<Database>(
    SUPABASE_URL as string,
    SUPABASE_PUBLISHABLE_KEY as string,
    {
      auth: {
        storage: localStorage,
        persistSession: true,
        autoRefreshToken: true,
      },
    },
  );
}

export const supabase: SupabaseClient<Database> = exportedClient;